head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf20000";
scwin._popupWindow = undefined;
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_entryDefaults
 * @description 진입 파라미터 기본값 (회신표 entry_defaults — 전달분 우선). 진입점이 부르는 초기화 단계.
 * @returns {void}
 * @hidden N
 */
scwin.init_entryDefaults = function () {
    const pcGubunRadio = $c.util.getComponent('dma_DownloadReq');
    if (!pcGubunRadio || typeof pcGubunRadio.get !== 'function') {
        /* TODO Stage2: [sdd] entry_defaults 대상 부재: dma_DownloadReq */
    } else if (($c.data.getParameter('gubunRadio') == null || $c.data.getParameter('gubunRadio') === '') && (pcGubunRadio.get('gubunRadio') == null || pcGubunRadio.get('gubunRadio') === '')) {
        pcGubunRadio.set('gubunRadio', "1");
    }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — thisServer, result, gubunRadio, curDate, std_cd_grnt_start_dd, std_cd_grnt_end_dd, searchRadio, searchRadio1, isur_cd, isur_nm, com_nm

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "ul_186", attr: "__html", fn: function () { return ([String(dma_page.get("total")), String(dma_page.get("currentPage")), String(dma_page.get("pageCount"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("총 <strong id=\"totPage\">" + String(dma_page.get("total")) + "</strong>건 <span id=\"totPage1\">(" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + ")</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_otherwise_54", fn: function(){ return (!(((dma_pageContext.get("thisServer") ?? "") === 'dr1') || ((dma_pageContext.get("thisServer") ?? "") === 'dr2') || ((dma_pageContext.get("thisServer") ?? "") === 'real1') || ((dma_pageContext.get("thisServer") ?? "") === 'real2'))); } }, { id: "if_result", fn: function(){ return (!(String(((dma_pageContext.get("result") ?? "")) == null ? '' : ((dma_pageContext.get("result") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_curSh", fn: function () { return String(String((dma_pageContext.get("curSh") ?? ""))); } },
        { childId: "ipt_isurNm", fn: function () { return String(String((dma_pageContext.get("isurNm") ?? ""))); } },
        { childId: "ipt_isurNm1", fn: function () { return String(String((dma_pageContext.get("isurNm") ?? ""))); } },
        { childId: "ipt_stdCdFind", fn: function () { return String(String((dma_pageContext.get("stdcdfind") ?? ""))); } },
        { childId: "ipt_comNm1", fn: function () { return String(String((dma_pageContext.get("comNm") ?? ""))); } },
        { childId: "ipt_isurCd1", fn: function () { return String(String((dma_pageContext.get("isurCd") ?? ""))); } },
        { childId: "cal_stdCdGrntStartDd", fn: function () { return String(String((dma_pageContext.get("stdCdGrntStartDd") ?? ""))); } },
        { childId: "cal_stdCdGrntEndDd", fn: function () { return String(String((dma_pageContext.get("stdCdGrntEndDd") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_datefmt_cal_stdCdGrntStartDd
 * @description 초기화 — datefmt cal std Cd Grnt Start Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_stdCdGrntStartDd = function () { $c.date.checkCalendarFormat("cal_stdCdGrntStartDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_stdCdGrntEndDd
 * @description 초기화 — datefmt cal std Cd Grnt End Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_stdCdGrntEndDd = function () { $c.date.checkCalendarFormat("cal_stdCdGrntEndDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const pageIndex = $c.util.getComponent('ipt_currentPage').getValue();
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        scwin.dateSetting();
        $('input[name=ipt_isurNm1]').keypress(async function(e) {
                if (e.keyCode === 13) {
                    await scwin.search('1');
                }
        });
        $('input[name=searchRadio]').bind("click", function() {
                $c.util.getComponent('ipt_curSh').setValue($(this).val());
                $('.paging').empty();
                const resetPaging = "<tr><td style='padding-left:5px'><img diabled src='/img/btn/btn-pprev.gif' alt=''></td><td style='padding-left:5px'><img src='/img/btn/btn-prev.gif' alt='' ></td><td class='bg_pagingbar'></td><td>1</td><td style='padding-left:5px'><img src='/img/btn/btn-next.gif' border='0' ></td><td style='padding-left:5px'><img src='/img/btn/btn-nnext.gif' alt='' ></a></td></tr>";
                $('.paging').append(resetPaging);
        });
        $c.util.getComponent("ipt_isurNm1").focus();
        const gubunRadio = (String(((dma_pageContext.get("gubunRadio") ?? "")) == null ? '' : ((dma_pageContext.get("gubunRadio") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("gubunRadio") ?? "")) == null ? '' : ((dma_pageContext.get("gubunRadio") ?? ""))));
        if (gubunRadio === '') {
            scwin.appDate2('stdCdGrntStartDd', 'stdCdGrntEndDd', 12);
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20000.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":4
        ,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf20000' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_entryDefaults();
        scwin.init_datefmt_cal_stdCdGrntStartDd();
        scwin.init_datefmt_cal_stdCdGrntEndDd();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf20000.onpageload' });
    }
};

