/**
 * @method
 * @name download
 * @description download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.download = async function () {
    await $c.win.alert("조회 내용이 없습니다.");
    return;
    if (($c.util.getComponent('cal_stdCdGrntStartDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntStartDd').getValue())) === '') {
        await $c.win.alert('다운로드는 일자를 1년 이내로 설정하여야\n\r사용이 가능합니다.');
        std_cd_grnt_start_dd.focus();
        return;
    } else {
        if (($c.util.getComponent('cal_stdCdGrntEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntEndDd').getValue())) === '') {
            await $c.win.alert('다운로드는 일자를 1년 이내로 설정하여야\n\r사용이 가능합니다.');
            std_cd_grnt_end_dd.focus();
            return;
        } else {
            const startD = $c.util.getComponent('cal_stdCdGrntStartDd').getValue();
            const startN = parseInt(startD.substr(4, 2), 10) - 1;
            const startT = new Date(startD.substr(0, 4), startN, startD.substr(6, 2));
            const endD = $c.util.getComponent('cal_stdCdGrntEndDd').getValue();
            const endN = parseInt(endD.substr(4, 2), 10) - 1;
            const endT = new Date(endD.substr(0, 4), endN, endD.substr(6, 2));
            const apDate = new Date(endT - 365 * 1000 * 60 * 60 * 24);
            if (apDate - startT > 0) {
                await $c.win.alert('다운로드는 일자를 1년 이내로 설정하여야\n\r사용이 가능합니다.');
                std_cd_grnt_start_dd.focus();
                return;
            }
        }
    }
    await $c.win.alert("다운로드는 데이터에 따라 몇초에서 몇분가량 소요될 수 있습니다.");
    $c.util.getComponent('ipt_isurCd').setValue(($c.util.getComponent("ipt_isurCd1").getValue() || ''));
    $c.util.getComponent('ipt_comNm').setValue(($c.util.getComponent("ipt_comNm1").getValue() || ''));
    const frm = (document.JLDINF20000 || { elements: [] });
    if ($('#ipt_searchRadio10').is(":checked")) {
        frm.action = "/srch/srch.do?method=srchDownElsdlsList";
    } else {
        if ($('#ipt_searchRadio11').is(":checked")) {
            frm.action = "/srch/srch.do?method=srchDownElwList";
        } else {
            if ($('#ipt_searchRadio16').is(":checked")) {
                frm.action = "/srch/srch.do?method=srchDownEtnList";
            }
        }
    }
    frm.method = "post";
    frm.target = "iframeExcel";
    await scwin.tx_fn_Download();
};

/**
 * @method
 * @name searchData
 * @description search Data 처리
 * @param {Number} idx idx
 * @returns {void}
 * @hidden N
 */
scwin.searchData = function (idx) {
    let std_cd_grnt_start_dd = (String(((dma_pageContext.get("std_cd_grnt_start_dd") ?? "")) == null ? '' : ((dma_pageContext.get("std_cd_grnt_start_dd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("std_cd_grnt_start_dd") ?? "")) == null ? '' : ((dma_pageContext.get("std_cd_grnt_start_dd") ?? ""))));
    let std_cd_grnt_end_dd = (String(((dma_pageContext.get("std_cd_grnt_end_dd") ?? "")) == null ? '' : ((dma_pageContext.get("std_cd_grnt_end_dd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("std_cd_grnt_end_dd") ?? "")) == null ? '' : ((dma_pageContext.get("std_cd_grnt_end_dd") ?? ""))));
    const searchRadio2 = (String(((dma_pageContext.get("searchRadio") ?? "")) == null ? '' : ((dma_pageContext.get("searchRadio") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("searchRadio") ?? "")) == null ? '' : ((dma_pageContext.get("searchRadio") ?? ""))));
    const searchRadio1 = (String(((dma_pageContext.get("searchRadio1") ?? "")) == null ? '' : ((dma_pageContext.get("searchRadio1") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("searchRadio1") ?? "")) == null ? '' : ((dma_pageContext.get("searchRadio1") ?? ""))));
    const searchRadio = $c.util.getComponent('ipt_curSh').getValue();
    const isur_cd = (String(((dma_pageContext.get("isur_cd") ?? "")) == null ? '' : ((dma_pageContext.get("isur_cd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isur_cd") ?? "")) == null ? '' : ((dma_pageContext.get("isur_cd") ?? ""))));
    const isur_nm = (String(((dma_pageContext.get("isur_nm") ?? "")) == null ? '' : ((dma_pageContext.get("isur_nm") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isur_nm") ?? "")) == null ? '' : ((dma_pageContext.get("isur_nm") ?? ""))));
    const com_nm = (String(((dma_pageContext.get("com_nm") ?? "")) == null ? '' : ((dma_pageContext.get("com_nm") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("com_nm") ?? "")) == null ? '' : ((dma_pageContext.get("com_nm") ?? ""))));
    if (std_cd_grnt_start_dd === '11111111') {
        std_cd_grnt_start_dd = '';
    }
    if (std_cd_grnt_end_dd === '99999999') {
        std_cd_grnt_end_dd = '';
    }
    if ((std_cd_grnt_start_dd === "" && std_cd_grnt_end_dd === "") && searchRadio1 === "") {
        const now = new Date();
        const year = now.getFullYear();
        const mon = (now.getMonth() + 1) > 9 ? '' + (now.getMonth() + 1) : '0' + (now.getMonth() + 1);
        const day = now.getDate() > 9 ? '' + now.getDate() : '0' + now.getDate();
        const toDate = year + mon + day;
        const n = parseInt(toDate.substr(4, 2), 10) - 1;
        const st = new Date(toDate.substr(0, 4), n, toDate.substr(6, 2));
        const apDate = new Date(st - 30 * 1000 * 60 * 60 * 24);
        const startDate = apDate.getFullYear() + "" + $c.str.lpad(String(apDate.getMonth() + 1), 2, '0') + "" + $c.str.lpad(String(apDate.getDate()), 2, '0');
        std_cd_grnt_start_dd = startDate;
        std_cd_grnt_end_dd = toDate;
        $c.util.getComponent('cal_stdCdGrntStartDd').setValue(std_cd_grnt_start_dd);
        $c.util.getComponent('cal_stdCdGrntEndDd').setValue(std_cd_grnt_end_dd);
    }
    const isur_cd_leng = $('#ipt_isurCd1').length;
    if (isur_cd_leng > 0) {
        $c.util.getComponent('ipt_isurCd1').setValue(isur_cd);
        $c.util.getComponent('ipt_comNm1').setValue(com_nm);
    }
    const isur_nm_leng = $('#ipt_isurNm1').length;
    if (isur_nm_leng > 0) {
        $c.util.getComponent('ipt_isurNm1').setValue(isur_nm);
    }
    $c.util.getComponent('cal_stdCdGrntStartDd').setValue(std_cd_grnt_start_dd);
    $c.util.getComponent('cal_stdCdGrntEndDd').setValue(std_cd_grnt_end_dd);
    $('input[name=searchRadio][value="' + searchRadio + '"]').attr("checked", true);
};

