/**
 * @method
 * @name search
 * @description search 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (idx) {
    const gubun = $c.util.getComponent("dma_DownloadReq").get("gubunRadio");
    if (gubun === '1') {
        if (($c.util.getComponent('ipt_isurNm1').getValue() == null ? '' : String($c.util.getComponent('ipt_isurNm1').getValue())) === '') {
            await $c.win.alert("한글종목명 및 표준코드을 입력하세요.");
            $c.util.getComponent("ipt_isurNm1").focus();
            return;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_isurNm1').getValue()) <= 2) {
            await $c.win.alert("한글종목명 및 표준코드을 확인하세요");
            $c.util.getComponent("ipt_isurNm1").focus();
            return;
        }
        $('input[name=searchRadio][value=1]').attr("checked", true);
        $c.util.getComponent('ipt_isurNm').setValue(($c.util.getComponent("ipt_isurNm1").getValue() || ''));
    } else {
        if (gubun === '2') {
            if (($c.util.getComponent('ipt_comNm1').getValue() == null ? '' : String($c.util.getComponent('ipt_comNm1').getValue())) === '') {
                await $c.win.alert("발행기관을 선택하세요.");
                return;
            }
            $('input[name=searchRadio][value=1]').attr("checked", true);
            $c.util.getComponent('ipt_isurCd').setValue(($c.util.getComponent("ipt_isurCd1").getValue() || ''));
            $c.util.getComponent('ipt_comNm').setValue(($c.util.getComponent("ipt_comNm1").getValue() || ''));
        } else {
            if (gubun === '3') {
                $c.util.getComponent('ipt_isurCd').setValue(($c.util.getComponent("ipt_isurCd1").getValue() || ''));
                $c.util.getComponent('ipt_comNm').setValue(($c.util.getComponent("ipt_comNm1").getValue() || ''));
            }
        }
    }
    const frm = (document.JLDINF20000 || { elements: [] });
    if (idx === '1') {
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    frm.action = "/srch/srch.do?method=srchList";
    frm.target = "_self";
    blockLoading();
    await scwin.tx_fn_search();
    const dateGubun = $c.util.getComponent("dma_DownloadReq").get("searchDateRadio");
    if (dateGubun === "4") {
        scwin.viewDownloadBtn("Y");
    } else {
        scwin.viewDownloadBtn("N");
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_263_onclick
 * @description krxpage_pagenavigator_263 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_263_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_263.page' }); } await scwin.tx_fn_search(); };
